{
  "title": "图书馆的秘密",
  "scene": "李明在图书馆做复习，忽然听到有人低语。一名学长似乎在抱怨考试作弊被抓的后果，而一名学妹则在说要偷偷把一份密卷藏起来。李明犹豫着要不要去调查或直接离开。",
  "goal": "李明需要做出一个不会泄露自己知晓内情的决定。",
  "clue": "学长提到的‘被抓’和学妹提到的‘密卷’是做决策的关键。",
  "choices": [
    {
      "id": "A",
      "text": "调查声音来源",
      "outcome": "李明走近查看，发现是两位学弟为了逃避处罚而编造的谎言。虽然避免了直接揭露事实，但李明感到不安，担心自己被卷入不必要的麻烦。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "默默离开图书馆",
      "outcome": "李明直接离开了，但心里还是忐忑不安，担心学长说的被抓后果是否真实。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "询问学长学妹",
      "outcome": "李明询问学长学妹，得知密卷是学长自己伪造的，用来在考试中作弊。学长怕被抓，学妹则希望保留密卷。李明巧妙地表示自己知道一些事情，但不会曝光他们，反而用这个机会，和学长讨论了考试策略，避免了正面冲突，同时得到更多复习资料。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
